window.addEventListener('orientationchange',clearInputs);
function input(dt){keyGas=pedalRamp(keyGas,keys.has('w')||keys.has('arrowup'),dt,1.6,4);keyBrake=pedalRamp(keyBrake,keys.has('s')||keys.has('arrowdown'),dt,3,5);let gas=Math.max(touchGas,keyGas),brake=Math.max(touchBrake,keyBrake),steer=touchSteer+(keys.has('a')||keys.has('arrowleft')?-1:0)+(keys.has('d')||keys.has('arrowright')?1:0),boost=touchBoost||keys.has(' ');let pad=navigator.getGamepads?.()[0];if(pad){steer+=Math.abs(pad.axes[0])>.06?pad.axes[0]:0;gas=Math.max(gas,pad.buttons[7]?.value||0);brake=Math.max(brake,pad.buttons[6]?.value||0);boost ||=pad.buttons[0]?.pressed;}if(mode!=='lab'&&$('autoGas').checked)gas=Math.max(gas,1-brake);throttleInput=gas;brakeInput=brake;steerInput=clamp(steer,-1,1);boostInput=boost;return{gas,brake,steer:steerInput,boost};}
function updateAI(d,dt){const skill={easy:.66,normal:.80,hard:.93}[difficulty]*d.aiSkill;let offset=Math.sin(d.distance/180+d.id)*.65;for(let other of drivers){if(other===d)continue;let gap=other.distance-d.distance;if(gap>0&&gap<26&&Math.abs(other.near.offset-d.near.offset)<2.5){offset=d.id%2?2.6:-2.6;break;}}d.aiOffset=lerp(d.aiOffset,offset,Math.min(1,dt));const controls=aiControls(d,skill,d.aiOffset);drive(d,controls,dt,true);d.aiSpeed=d.speed;d.aiD=d.distance;if(d.offTime>3||d.speed<1&&d.lapTime>15){d.stuck=(d.stuck||0)+dt;if(d.stuck>4){recover(d);d.stuck=0;}}else d.stuck=0;if(d.distance>=LENGTH*3&&!d.finished){d.finished=true;d.finishTime=raceTime;d.finishPlace=++finishRank;}}
function finish(){player.finished=true;player.finishTime=raceTime;player.finishPlace=++finishRank;state='finished';clearInputs();$('results').classList.remove('hidden');let rank=player.finishPlace;$('resultTitle').textContent=rank===1?'冠軍。屬於你。':rank<=3?`P${rank} · 站上頒獎台`:`P${rank} · 完成大獎賽`;$('resultSummary').textContent=`總時間 ${formatTime(raceTime)}　／　最佳圈 ${player.best?formatTime(player.best):'無有效圈速'}`;let sorted=[...drivers].sort((a,b)=>a.finished&&b.finished?a.finishPlace-b.finishPlace:a.finished?-1:b.finished?1:b.distance-a.distance);$('resultTable').innerHTML=sorted.map((d,i)=>`<div class="resultRow ${d.player?'you':''}"><span>${i+1}</span><span>${d.name}${d.player?' / PLAYER':''}</span><span>${d.finished?formatTime(d.finishTime):'未完賽'}</span></div>`).join('');}
function physics(dt){if(state==='countdown'){countdown-=dt;let lit=clamp(Math.floor(5.2-countdown),0,5);[...$('startLights').querySelectorAll('i')].forEach((el,i)=>el.classList.toggle('on',i<lit));$('startLights').querySelector('span').textContent=countdown<.4?'等待熄燈':'準備起跑';if(countdown<=0){state='race';$('startLights').classList.add('hidden');message('LIGHTS OUT · 全力起跑！',2.5);beep(880,.12);}return;}if(state!=='race')return;raceTime+=dt;const controls=input(dt);if(player.recoveryHold>0){player.recoveryHold-=dt;controls.gas=0;controls.brake=1;}if(mode==='lab'){drive(player,controls,dt,labPanel.assist.checked,LAB_ENVIRONMENT);labSnapshot=labObserver.sample(player);return;}drive(player,controls,dt,$('assist').checked);for(let d of drivers)if(!d.player&&!d.finished)updateAI(d,dt);for(let i=0;i<drivers.length;i++)for(let j=i+1;j<drivers.length;j++){let a=drivers[i],b=drivers[j];if(collide(a,b)&&(a.player||b.player)&&player.collisionCooldown<=0){player.collisionCooldown=.7;shake=.22;$('damageFlash').style.opacity='.5';setTimeout(()=>$('damageFlash').style.opacity='0',100);impact();}}

if(player.wallHit){player.wallHit=false;shake=.3;impact();}if(player.offTime>4){recover(player);player.recoveryHold=3;message('返回賽道 · 停車 3 秒');cameraSnap=true;}if(player.justLapped){let result=player.justLapped;player.justLapped=null;if(result.valid){message(`第 ${player.completed} 圈 · ${formatTime(result.time)}`);if(!bestStored||result.time<bestStored){bestStored=result.time;try{localStorage.setItem('apex-four-wheel-alpine-v1-best',String(bestStored));}catch{}$('best').textContent=formatTime(bestStored);}}else message('本圈超出賽道邊界 · 圈速無效');}if(mode==='race'&&player.distance>=LENGTH*3&&!player.finished)finish();}
function updateModels(dt){for(let d of drivers){d.model.position.set(d.x,.012,d.z);d.model.rotation.set(0,d.a,0);for(let w of d.model.userData.wheels){let physical=d.wheels.find(t=>t.id===w.id);w.pivot.rotation.y=physical?.steer||0;w.rolling.rotation.x=physical?.angle||0;}}}
function cameraUpdate(dt,now){if(state==='menu'){let t=now*.00009,a=showcase.a+t;camera.position.set(showcase.x+Math.sin(a)*8.5,3.5,showcase.z+Math.cos(a)*8.5);camera.lookAt(showcase.x,.56,showcase.z);camera.setViewOffset(innerWidth,innerHeight,innerWidth>700?-innerWidth*.15:0,0,innerWidth,innerHeight);camera.fov=43;camera.updateProjectionMatrix();return;}if(!player)return;if(mode==='lab'){player.model.visible=true;labScene.update(player,camera,cameraMode,$('labStage').getBoundingClientRect(),{width:innerWidth,height:innerHeight});return;}camera.clearViewOffset();let a=player.a,fx=Math.sin(a),fz=Math.cos(a),speed=player.speed,portrait=innerHeight>innerWidth;player.model.visible=cameraMode!==2;if(cameraMode>0){const pose=fixedCameraPose(player,cameraMode,portrait);const mount=player.model.userData.cameraMounts?.[cameraMode];if(mount)camera.position.copy(player.model.localToWorld(tmp.set(mount.x,mount.y,mount.z)));else camera.position.set(pose.x,pose.y+.012,pose.z);camera.quaternion.setFromEuler(new THREE.Euler(pose.pitch,pose.yaw,0,'YXZ'));camera.fov=pose.fov;cameraSnap=false;}else{let back=portrait?11:9.5;tmp.set(player.x-fx*back,portrait?4.6:3.5,player.z-fz*back);let lookAhead=(portrait?3:7)+speed*(portrait?.10:.14);cameraLook.set(player.x+fx*lookAhead,1.05,player.z+fz*lookAhead);let smoothing=1-Math.exp(-dt*7.5);if(cameraSnap){camera.position.copy(tmp);cameraPos.copy(cameraLook);cameraSnap=false;}else{camera.position.lerp(tmp,smoothing);cameraPos.lerp(cameraLook,Math.min(1,smoothing*1.2));}if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake*.35;}camera.lookAt(cameraPos);camera.fov=lerp(camera.fov,(portrait?68:60)+clamp(speed/90,0,1)*8,Math.min(1,dt*3));}shake=Math.max(0,shake-dt);camera.updateProjectionMatrix();sun.position.set(player.x-70,140,player.z+65);sun.target.position.set(player.x,0,player.z);sun.target.updateMatrixWorld();}
const mapCtx=$('map').getContext('2d');let minX=Math.min(...path.map(p=>p.x)),maxX=Math.max(...path.map(p=>p.x)),minZ=Math.min(...path.map(p=>p.z)),maxZ=Math.max(...path.map(p=>p.z));function mapPoint(x,z){let scale=Math.min(180/(maxX-minX),120/(maxZ-minZ));return[15+(x-minX)*scale,15+(z-minZ)*scale];}function drawMap(){mapCtx.clearRect(0,0,210,150);mapCtx.beginPath();path.forEach((p,i)=>{let a=mapPoint(p.x,p.z);i?mapCtx.lineTo(...a):mapCtx.moveTo(...a);});mapCtx.closePath();mapCtx.strokeStyle='#6c8997';mapCtx.lineWidth=5;mapCtx.stroke();mapCtx.strokeStyle='#c4d6d8';mapCtx.lineWidth=1.5;mapCtx.stroke();for(let d of drivers){let p=mapPoint(d.x,d.z);mapCtx.fillStyle=d.player?'#dcff49':d.color;mapCtx.beginPath();mapCtx.arc(...p,d.player?4:2.6,0,Math.PI*2);mapCtx.fill();}}
function updateHud(){if(!player||state==='menu')return;if(mode==='lab'){if(labSnapshot)labPanel.update(labSnapshot,{paused:state==='paused',view:['觀測','側視','俯視'][cameraMode]});for(const [id,value] of [['gas',player.throttle],['brake',player.brake]]){$(id+'Percent').textContent=`${Math.round(value*100)}%`;$(id).style.setProperty('--pedal',`${value*100}%`);}return;}let order=[...drivers].sort((a,b)=>a.finished&&b.finished?a.finishPlace-b.finishPlace:a.finished?-1:b.finished?1:b.distance-a.distance);$('position').textContent=order.indexOf(player)+1;$('lap').textContent=Math.min(mode==='race'?3:999,Math.max(1,Math.floor(player.distance/LENGTH)+1));$('lapTime').textContent=formatTime(player.lapTime);$('lapTime').style.color=player.invalid?'#ff9d85':'white';let speed=player.speed*3.6,gear=speed<2?'N':Math.min(8,Math.floor(speed/44)+1);$('speed').textContent=Math.round(speed);$('gear').textContent=gear;$('ers').textContent=Math.round(player.ers);$('gasBar').style.width=`${player.throttle*100}%`;$('brakeBar').style.width=`${player.brake*100}%`;for(const [id,value] of [['gas',player.throttle],['brake',player.brake]]){$(id+'Percent').textContent=`${Math.round(value*100)}%`;$(id).style.setProperty('--pedal',`${value*100}%`);}let rpm=speed<2?.12:.32+(speed%44)/44*.68;revs.forEach((r,i)=>{r.classList.toggle('lit',i<rpm*12);r.classList.toggle('red',i>8);});for(let d of order){let row=$('leaderboard').querySelector(`[data-id="${d.id}"]`);row.style.order=order.indexOf(d);row.classList.toggle('mobileHide',order.indexOf(d)>2&&!d.player);row.querySelector('em').textContent=order.indexOf(d)+1;row.querySelector('small').textContent=d.player?'PLAYER':d.finished?'FIN':`+${Math.max(0,(order[0].distance-d.distance)/Math.max(20,d.speed)).toFixed(1)}`;}$('leaderboard').style.display='flex';$('leaderboard').style.flexDirection='column';let facing=Math.abs(angleDiff(player.a,player.near.a));$('wrongWay').classList.toggle('hidden',!(facing>2.1&&player.speed>3&&state==='race'));const offWheels=player.wheels.filter(w=>w.surface==='grass'||w.surface==='gravel').length;$('trackStatus').textContent=offWheels?`${offWheels} 輪駛離賽道 · 抓地力降低`:'乾地 · 四輪獨立物理';for(const w of player.wheels){const node=$('tyre'+w.id);node.querySelector('b').textContent=`${(w.fz/1000).toFixed(1)}kN`;node.querySelector('small').textContent=`${w.surface==='asphalt'?'柏油':w.surface==='curb'?'路緣':w.surface==='grass'?'草地':'碎石'} 有效 μ${(w.fz>0?w.capacity/w.fz:0).toFixed(2)}`;node.style.setProperty('--use',`${w.utilization*100}%`);node.classList.toggle('off',w.surface==='grass'||w.surface==='gravel');}drawMap();}
const engineAudio=createEngineAudio({onStatus:({enabled,state})=>{$('sound').textContent=enabled?(state==='running'?'音效 開':'點按開聲'):'音效 關';$('sound').setAttribute('aria-pressed',String(enabled));}});
function initAudio(){return engineAudio.unlock();}
$('sound').onclick=()=>{if(engineAudio.enabled&&engineAudio.state!=='running')engineAudio.unlock();else engineAudio.setEnabled(!engineAudio.enabled);};
// Resume inside the gesture itself: mobile Safari may interrupt audio after backgrounding.
window.addEventListener('pointerdown',e=>{if(!e.target.closest?.('#sound')&&engineAudio.enabled&&engineAudio.state!=='running')engineAudio.unlock();},{capture:true,passive:true});
window.addEventListener('keydown',()=>{if(engineAudio.enabled&&engineAudio.state!=='running')engineAudio.unlock();});
function beep(freq,dur){engineAudio.beep(freq,dur);}function impact(){engineAudio.beep(70,.15);}
function updateAudio(){const rear=player?.wheels.filter(w=>!w.front)||[];engineAudio.update({active:['race','countdown'].includes(state),garage:state==='menu',hidden:document.hidden,speed:player?.speed||0,throttle:player?.throttle||0,rearWheelSpeed:rear.length?rear.reduce((sum,w)=>sum+Math.abs(w.omega)*PHYSICS.wheelRadius,0)/rear.length:0});}
document.addEventListener('visibilitychange',()=>{if(document.hidden)engineAudio.update({hidden:true});});
function resize(){camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);cameraSnap=true;}window.addEventListener('resize',resize);canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(['race','countdown'].includes(state))pause();message('圖形暫停，請重新整理頁面');});
function loop(now){let dt=Math.min(.05,(now-lastFrame)/1000||.016);lastFrame=now;if(state==='race'||state==='countdown'){acc+=dt;while(acc>=1/120){physics(1/120);acc-=1/120;}}else acc=0;if(messageTime>0){messageTime-=dt;if(messageTime<=0)$('message').classList.remove('show');}updateModels(dt);tyreSmoke.update(state==='paused'?0:dt,drivers,state==='race');cameraUpdate(dt,now);uiTimer+=dt;if(uiTimer>.08){uiTimer=0;updateHud();}updateAudio();renderer.render(scene,camera);requestAnimationFrame(loop);}
$('loading').classList.add('hidden');applyQuality();requestAnimationFrame(loop);
// Read-only QA state makes race regressions inspectable without coupling UI to tests.
window.apexState=()=>({state,mode,lab:mode==='lab'?labSnapshot:null,touch:touchControls.state,audio:{enabled:engineAudio.enabled,state:engineAudio.state,...engineAudio.telemetry},smokeParticles:tyreSmoke.activeCount,length:LENGTH,camera:cameraMode,wheels:player?.wheels.map(w=>({id:w.id,fz:w.fz,mu:w.mu,effectiveMu:w.fz>0?w.capacity/w.fz:0,surface:w.surface,fx:w.fx,fy:w.fy,slip:w.slipRatio})),position:player?drivers.filter(d=>d.distance>player.distance).length+1:0,speed:player?.speed,lap:player?.completed,cars:drivers.length});
